package com.travbook.railtickets.adapter.out.commerce;
import com.travbook.railtickets.application.port.out.RailTicketEffects;
import com.travbook.railtickets.domain.model.RailTicket.*;
import com.travbook.railtickets.application.port.out.RailReservations;
import com.travbook.payments.application.port.in.*;
import java.util.*;
public final class RailTicketEffectAdapter implements RailTicketEffects {
 private final PaymentOperations payments;private final PaymentRefunds refunds;private final RailReservations supplier;
 public RailTicketEffectAdapter(PaymentOperations payments,PaymentRefunds refunds,RailReservations supplier){this.payments=payments;this.refunds=refunds;this.supplier=supplier;}
 public Optional<Result> lookup(Booking b,Step step){UUID op=b.operation(step==Step.REFUND_STATUS?Step.REFUND:step);if(step==Step.CANCEL&&b.passengerChanges())return supplier.lookupPassengers(op).map(r->{if(!r.operationId().equals(op)||!r.reservationId().equals(b.id())||!r.mode().equals("MOCK")||!r.reference().equals("MOCK-PNR-"+b.id())||!r.passengerIndexes().equals(b.cancellationScope())||r.remaining()!=b.activePassengers().size()-b.cancellationScope().size())throw new IllegalStateException("Passenger receipt binding mismatch");return new Result(true,true,r.reference(),r.remaining()==0?Reservation.CANCELLED:b.reservation());});return switch(step){case AUTHORIZE,CAPTURE,VOID->payments.lookup(op).map(r->{check(b,r.paymentId(),r.amount(),r.currency(),r.mode());String expected=switch(step){case AUTHORIZE->"AUTHORIZED";case CAPTURE->"CAPTURED";case VOID->"VOIDED";default->throw new IllegalStateException();};if(!r.operationId().equals(op)||r.accepted()!=r.state().name().equals(expected)||!r.accepted()&&!(step==Step.AUTHORIZE&&r.state()==com.travbook.payments.domain.model.Payment.State.DECLINED||step==Step.CAPTURE&&r.state()==com.travbook.payments.domain.model.Payment.State.AUTHORIZED)||r.reference()==null||!r.reference().startsWith("MOCK-PAY-"))throw new IllegalStateException("Payment receipt state or operation mismatch");return new Result(r.accepted(),true,r.reference(),null);});case RESERVE,CANCEL->supplier.lookup(op).map(r->{boolean accepted=step==Step.RESERVE?com.travbook.railtickets.domain.model.RailTicket.issuedReservation(r.status()):r.status()==Reservation.CANCELLED;if(!r.operationId().equals(op)||!r.reservationId().equals(b.id())||!r.mode().equals("MOCK")||r.accepted()!=accepted||step==Step.RESERVE&&r.accepted()&&r.status()!=com.travbook.railtickets.domain.model.RailTicket.expectedReservation(b.quote().selection().availability())||!r.accepted()&&r.status()!=Reservation.REJECTED||!r.reference().equals("MOCK-PNR-"+b.id()))throw new IllegalStateException("Rail provider binding mismatch");return new Result(r.accepted(),true,r.reference(),r.status());});case REFUND,REFUND_STATUS->refunds.lookup(op).map(r->{if(!r.operationId().equals(op)||!r.paymentId().equals(b.id())||!r.mode().equals("MOCK")||!r.currency().equals("INR")||r.amount().compareTo(b.cancellation().quote().refundAmount().amount())!=0||r.reference()==null||!r.reference().startsWith("MOCK-REFUND-"))throw new IllegalStateException("Refund binding mismatch");return new Result(true,r.completed(),r.reference(),null);});default->Optional.empty();};}
 private void check(Booking b,UUID id,java.math.BigDecimal amount,String currency,String mode){if(!id.equals(b.id())||amount.compareTo(b.quote().selection().total().amount())!=0||!currency.equals("INR")||!mode.equals("MOCK"))throw new IllegalStateException("Payment binding mismatch");}
 public Result execute(Booking b,Step step){UUID op=b.operation(step==Step.REFUND_STATUS?Step.REFUND:step);switch(step){
  case AUTHORIZE,CAPTURE,VOID->{payments.execute(new PaymentOperations.Command(op,b.id(),b.quote().owner(),com.travbook.payments.domain.model.Payment.Operation.valueOf(step.name()),b.quote().selection().total().amount(),"INR",b.quote().effectiveExpiry(),step==Step.AUTHORIZE&&b.scenario()==Scenario.AUTH_DECLINED||step==Step.CAPTURE&&b.scenario()==Scenario.CAPTURE_DECLINED));if(step==Step.CAPTURE&&b.scenario()==Scenario.CAPTURE_RESPONSE_LOST)throw new IllegalStateException("Simulated capture response loss");}
  case RESERVE->{supplier.reserve(op,b.id(),b.quote(),b.scenario()==Scenario.RESERVATION_REJECTED);if(b.scenario()==Scenario.RESERVATION_RESPONSE_LOST)throw new IllegalStateException("Simulated reservation response loss");}
  case CANCEL->{if(b.passengerChanges())supplier.cancelPassengers(op,b.id(),b.cancellationScope());else supplier.cancel(op,b.id());if(b.cancellation()!=null&&b.cancellation().simulateResponseLoss())throw new IllegalStateException("Simulated cancellation response loss");}
  case REFUND->{var c=b.cancellation();refunds.submit(new PaymentRefunds.Command(op,b.id(),b.quote().owner(),c.quote().id(),c.quote().refundAmount().amount(),"INR",c.simulateDelay(),b.correlationId(),c.commandId()));if(c.simulateResponseLoss())throw new IllegalStateException("Simulated refund response loss");}
  case REFUND_STATUS->throw new IllegalStateException("Pending refund has no provider receipt");
  default->throw new IllegalStateException("Unsupported effect");
 }return lookup(b,step).orElseThrow();}

 public Optional<com.travbook.shared.domain.Recovery.Proof> verifiedLegacyOutcome(Booking b){
  if(b.status()!=Status.REVIEW||b.passengerChanges())return Optional.empty();
  var pay=payments.current(b.id()).orElse(null);var allocation=supplier.current(b.id()).orElse(null);
  if(pay==null||allocation==null||!pay.paymentId().equals(b.id())||!pay.owner().equals(b.quote().owner())||pay.state()!=com.travbook.payments.domain.model.Payment.State.CAPTURED||!pay.mode().equals("MOCK")||!pay.currency().equals("INR")||pay.amount().compareTo(b.quote().selection().total().amount())!=0||!allocation.reservationId().equals(b.id())||!allocation.mode().equals("MOCK")||!allocation.reference().equals("MOCK-PNR-"+b.id()))return Optional.empty();
  var capture=lookup(b,Step.CAPTURE).orElse(null);var reserve=lookup(b,Step.RESERVE).orElse(null);
  if(capture==null||reserve==null||!capture.accepted()||!reserve.accepted()||!capture.reference().equals(pay.reference())||!reserve.reference().equals(allocation.reference()))return Optional.empty();
  boolean fulfilled=b.cancellation()==null;String refundState="NONE",refundRef=null;int expectedUnits=b.quote().selection().passengers().size();
  if(fulfilled){if(!allocation.status().equals(com.travbook.railtickets.domain.model.RailTicket.expectedReservation(b.quote().selection().availability()).name())||allocation.activeUnits()!=expectedUnits||pay.committedRefunds().signum()!=0||pay.settledRefunds().signum()!=0)return Optional.empty();}
  else{var cancelled=lookup(b,Step.CANCEL).orElse(null);var amount=b.cancellation().quote().refundAmount().amount();if(cancelled==null||!cancelled.accepted()||!allocation.status().equals("CANCELLED")||allocation.activeUnits()!=0||pay.committedRefunds().compareTo(amount)!=0||pay.settledRefunds().compareTo(amount)!=0)return Optional.empty();if(amount.signum()>0){var refund=lookup(b,Step.REFUND).orElse(null);if(refund==null||!refund.completed())return Optional.empty();refundState="SUCCEEDED";refundRef=refund.reference();}else refundState="NOT_DUE";}
  return Optional.of(new com.travbook.shared.domain.Recovery.Proof(b.id(),fulfilled?com.travbook.shared.domain.Recovery.Outcome.FULFILLED:com.travbook.shared.domain.Recovery.Outcome.CANCELLED,"MOCK",pay.reference(),allocation.reference(),refundRef,allocation.status(),refundState,pay.amount(),pay.committedRefunds(),pay.settledRefunds(),pay.currency(),allocation.activeUnits(),b.operation(Step.CAPTURE),b.operation(Step.RESERVE),fulfilled?null:b.operation(Step.CANCEL),!fulfilled&&refundState.equals("SUCCEEDED")?b.operation(Step.REFUND):null));
 }
}
